const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function createFoundationShell(h){
 let globalsBound=false,commonMode=false,homeVisible=true,settings=h.desktopInfo?.settings||{},lastProject=null,logs=[],legacyImporter=null,libraryVisible=false,homeUpdateId=null,lastRecentMarkup=null;
 const p=h.getProject;
 const safeEdit=(...args)=>{try{return h.edit(...args);}catch(error){h.notify(error.message,true);h.render();}};
 document.querySelector('header').insertAdjacentHTML('beforeend','<button id="inspect-connections">연결 검사</button>');
 $('#inspect-connections').onclick=()=>{
   const doc=p();if(!doc){h.notify('프로젝트를 먼저 열어 주세요.');return;}
   const graph=dependencyGraph(doc),selected=h.getSelected(),impact=selected?affectedBy(doc,[selected]):null;
   const label=id=>doc.nodes.find(n=>n.id===id)?.name||doc.assets[id]?.name||doc.objects.find(o=>o.id===id)?.name||graph.vertices.find(n=>n.id===id)?.kind||id;
   h.showDialog(`<h2>연결 검사</h2><p>연결 ${graph.edges.length}개 · 확인할 문제 ${graph.diagnostics.length}개</p>${impact?`<h3>선택한 항목의 변경 영향</h3><p>설계 객체 ${impact.entityIds.length}개 · 생성 결과 ${impact.outputIds.length}개</p><ul>${impact.ids.map(id=>`<li>${esc(label(id))}</li>`).join('')}</ul>`:'<p>객체를 선택한 뒤 열면 변경에 영향을 받는 항목도 볼 수 있습니다.</p>'}${graph.diagnostics.length?'<p>누락되거나 순환하는 연결이 있습니다. 해당 연결을 수정한 뒤 생성하세요.</p>':'<p>등록된 연결에 누락·순환 문제가 없습니다.</p>'}<details><summary>검사 상세</summary><pre>${esc(JSON.stringify({diagnostics:graph.diagnostics,impactDiagnostics:impact?.diagnostics||[]},null,2))}</pre></details><p>연결 검사 결과이며, 기하 충돌·보행 검사는 별도 제작 항목입니다.</p>`);
 };
 const post=(url,body)=>h.api(url,{method:'POST',body:JSON.stringify(body)});
 const run=(label,fn)=>h.guard(async()=>{log(label);await fn();})();
 function log(text){logs.push({time:new Date().toLocaleTimeString(),text});if(logs.length>100)logs.shift();$('#foundation-log').textContent=logs.slice(-5).map(l=>l.time+' '+l.text).join('\n');}
 document.body.insertAdjacentHTML('beforeend',homeMarkup);
 $('header').insertAdjacentHTML('beforeend',`<button id="go-home">Home</button><button id="project-settings">프로젝트 설정</button><button id="project-copy">복제</button><button id="close-project">닫기</button><button id="panels">패널</button>`);
 $('.library').insertAdjacentHTML('afterbegin',`<details open id="foundation-tree"><summary>프로젝트 탐색기</summary><div class="node-create"><select id="node-type" aria-label="공통 객체 유형">${NODE_TYPES.map(t=>`<option>${t}</option>`).join('')}</select><button id="node-create">추가</button></div><div id="common-tree"></div></details>`);
 $('#import').insertAdjacentHTML('beforebegin',`<select id="asset-kind" aria-label="에셋 분류">${ASSET_KINDS.map(t=>`<option>${t}</option>`).join('')}</select>`);
 $('#files').accept+=',.json';$('#replace-file').accept+=',.json';
 const assetMonitor=createAssetStatus(h);
 const assetLibrary=createAssetLibrary({...h,updateAsset:a=>run('파일 변경 영향 확인',async()=>{const impact=await h.api('/api/foundation/'+a.id+'/usages');if(!confirm('이 파일을 사용하는 등록 프로젝트 '+new Set(impact.uses.map(u=>u.projectId)).size+'개입니다. 파일을 선택하면 구조 변경을 비교하며 기존 연결은 보존합니다. 업데이트할 파일을 선택할까요?'))return;homeUpdateId=a.id;$('#home-library-files').multiple=false;$('#home-library-files').value='';$('#home-library-files').click();})});
 $('#foundation-tree').append($('#objects'));$('.panel-switch').after($('#foundation-tree'));$('.outliner').remove();const advanced=document.createElement('details');advanced.id='advanced-node-create';advanced.innerHTML='<summary>고급 객체 추가</summary>';advanced.append($('.node-create'));$('#foundation-tree').append(advanced);
 const treeSearch=document.createElement('input');treeSearch.id='object-search';treeSearch.placeholder='객체 이름 검색';treeSearch.setAttribute('aria-label','객체 이름 검색');treeSearch.type='search';$('#foundation-tree').before(treeSearch);const noMatch=document.createElement('p');noMatch.id='object-search-empty';noMatch.hidden=true;noMatch.textContent='검색한 이름의 객체가 없습니다.';treeSearch.after(noMatch);treeSearch.oninput=filterTree;
 const projectMenu=document.createElement('details');projectMenu.id='project-menu';projectMenu.className='header-menu';projectMenu.innerHTML='<summary>프로젝트</summary><div></div>';$('#go-home').after(projectMenu);for(const id of ['#project-settings','#project-copy','#close-project','#inspect-connections','#roadmap'])projectMenu.querySelector('div').append($(id));projectMenu.addEventListener('click',e=>{if(e.target.closest('button'))projectMenu.open=false;});$('#go-home').textContent='홈';$('#panels').textContent='레이아웃';$('#project-menu > summary').textContent='프로젝트';
 
 const create=()=>{h.showDialog(`<h2>새 프로젝트</h2><label>이름<input id="foundation-name" maxlength="100" value="새 레벨"></label><label>저장 위치<input id="foundation-folder" placeholder="기본 Workspace에 독립 폴더 생성"></label><button type="button" id="pick-project-folder">위치 선택</button><label>폴더 사용 방식<select id="foundation-folder-mode"><option value="child">선택 위치 아래 프로젝트 이름으로 새 폴더 생성</option><option value="itself">선택한 빈 폴더 자체 사용</option></select></label><p id="folder-preview"></p><details><summary>좌표 고급 설정</summary><p>미터 · XY 평면 · Z 높이 · 오른손 좌표계<br>원점 자동 설정 [0, 0, 0] · 생성 후 설정에서 변경 가능</p></details><p class="hint">공용 라이브러리: ${esc(h.desktopInfo?.sharedRoot||'로컬')}</p><button type="button" id="foundation-create">프로젝트 만들기</button>`);const preview=()=>{$('#folder-preview').textContent='저장 폴더: '+($('#foundation-folder').value||h.desktopInfo?.workspace+'\\Projects')+($('#foundation-folder-mode').value==='child'?'\\'+$('#foundation-name').value:'');};for(const id of ['#foundation-name','#foundation-folder','#foundation-folder-mode'])$(id).oninput=preview;preview();$('#pick-project-folder').onclick=()=>run('프로젝트 위치 선택',async()=>{const r=await window.studioDesktop?.chooseFolder('new');if(r){$('#foundation-folder').value=r.path;preview();}});$('#foundation-create').onclick=()=>run('프로젝트 생성',async()=>{const doc=await post('/api/projects',{name:$('#foundation-name').value,folder:$('#foundation-folder').value||undefined,folderMode:$('#foundation-folder-mode').value});await h.refreshLibrary();$('#dialog').close();await h.openProject(doc.id);});};
 function bind(){
 $('#new-project').onclick=create;$('#home-new').onclick=create;
 $('#go-home').onclick=()=>home();
 $('#close-project').onclick=()=>run('프로젝트 닫기',async()=>{await h.wait();if(h.isFailed())throw Error('저장 실패를 먼저 해결하세요. 편집은 유지됩니다.');await h.openProject('');home();});
 $('#home-open').onclick=()=>{h.showDialog('<h2>프로젝트 열기</h2><button type="button" id="open-folder-action">프로젝트 폴더 선택</button><details><summary>이전 버전에서 가져오기</summary><button type="button" id="home-import">0.3 프로젝트 사본 가져오기</button></details>');$('#open-folder-action').onclick=()=>run('프로젝트 열기',async()=>{const doc=await window.studioDesktop?.chooseFolder('open');if(doc){$('#dialog').close();await h.refreshLibrary();await h.openProject(doc.id);}});$('#home-import').onclick=()=>legacyImporter();};
 $('#home-library').onclick=()=>{libraryVisible=true;assetLibrary.home();renderHome();};
 $('#home-projects').onclick=()=>{libraryVisible=false;renderHome();};
 $('#home-asset-search').oninput=renderHome;$('#home-library-import').onclick=()=>{homeUpdateId=null;$('#home-library-files').multiple=true;$('#home-library-files').value='';$('#home-library-files').click();};
 $('#home-library-files').onchange=()=>run('공용 파일 등록',async()=>{for(const file of $('#home-library-files').files){if(file.size>48*1024*1024)throw Error('파일당 최대 48MB입니다.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await post('/api/assets',{assetId:homeUpdateId||undefined,name:file.name,content,category:/\.(glb|fbx)$/i.test(file.name)?'Model':'Texture',sourcePath:window.studioDesktop?.filePath(file)||undefined});}homeUpdateId=null;await h.refreshLibrary();renderHome();h.notify('공용 라이브러리에 등록 또는 갱신했습니다.');});
 legacyImporter=()=>run('기존 프로젝트 목록 읽기',async()=>{const source=await window.studioDesktop?.chooseFolder('legacy');if(!source)return;h.showDialog(`<h2>기존 프로젝트 사본 가져오기</h2><p>원본 폴더는 수정하지 않습니다.</p>${source.projects.map(a=>`<button type="button" data-legacy="${a.id}">${esc(a.name)}</button>`).join('')}`);document.querySelectorAll('[data-legacy]').forEach(b=>b.onclick=()=>run('0.3 데이터 변환',async()=>{const doc=await post('/api/foundation/import',{sourceRoot:source.sourceRoot,id:b.dataset.legacy});await h.refreshLibrary();$('#dialog').close();await h.openProject(doc.id);}));});
 $('#home-preferences').onclick=preferences;
 $('#recent-search').oninput=renderHome;
 $('#node-create').onclick=()=>{commonMode=true;safeEdit(()=>{applyNodeCommand(p(),{type:'create',nodeType:$('#node-type').value});h.setSelected(p().nodes.at(-1).id);},'공통 객체 생성','common');};
 $('#project-settings').onclick=projectSettings;
 $('#project-copy').onclick=()=>{if(!p())return;h.showDialog(`<h2>프로젝트 복제</h2><label>새 이름<input id="copy-name" value="${esc(p().name)} 복사본"></label><p>독립 프로젝트 ID와 데이터 사본을 만듭니다. 원본은 보존합니다.</p><button type="button" id="copy-confirm">복제 만들기</button>`);$('#copy-confirm').onclick=()=>run('프로젝트 복제',async()=>{await h.wait();if(h.isFailed())throw Error('저장 실패 상태');const doc=await post('/api/foundation/duplicate',{id:p().id,name:$('#copy-name').value});await h.refreshLibrary();$('#dialog').close();await h.openProject(doc.id);});};
 $('#panels').onclick=()=>{h.showDialog(`<h2>편집기 패널</h2><label><input id="panel-left" type="checkbox" ${$('.library').hidden?'':'checked'}>왼쪽 탐색기</label><label><input id="panel-right" type="checkbox" ${$('.inspector').hidden?'':'checked'}>오른쪽 Inspector</label><button type="button" id="reset-panels">기본 크기 복원</button>`);for(const [id,selector]of [['#panel-left','.library'],['#panel-right','.inspector']])$(id).onchange=e=>{document.querySelector(selector).hidden=!e.target.checked;updateLayout();};$('#reset-panels').onclick=()=>{document.documentElement.style.setProperty('--foundation-left','270px');document.documentElement.style.setProperty('--foundation-right','300px');$('.library').hidden=false;$('.inspector').hidden=false;updateLayout();};};
 if(!globalsBound){globalsBound=true;
 document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();h.save();return;}if(e.target.matches('input,textarea,[contenteditable="true"]'))return;if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();}if(e.ctrlKey&&e.key.toLowerCase()==='y'){e.preventDefault();$('#redo').click();}if(e.key==='Delete'&&p()?.nodes.some(n=>n.id===h.getSelected())){e.preventDefault();removeNode();}});
 for(const selector of ['.library','.inspector']){const handle=document.createElement('div');handle.className='panel-resizer';document.querySelector(selector).append(handle);handle.onpointerdown=e=>{handle.setPointerCapture(e.pointerId);const start=e.clientX,width=document.querySelector(selector).getBoundingClientRect().width;handle.onpointermove=ev=>{const value=Math.min(500,Math.max(180,width+(selector==='.library'?1:-1)*(ev.clientX-start)));document.documentElement.style.setProperty(selector==='.library'?'--foundation-left':'--foundation-right',value+'px');};handle.onpointerup=()=>{handle.onpointermove=null;persistPanels();};};}
 document.addEventListener('pointerdown',e=>{if(e.target.closest('#objects,#planner-canvas,#design-inspection,#viewport,#asset-list,#clear-selection'))commonMode=false;},true);
 }
 }
 function filterTree(){const query=$('#object-search').value.trim().toLocaleLowerCase();let matches=0;for(const row of document.querySelectorAll('#common-tree .common-node,#objects .tree-entity,#objects > .tree-group > .object-row')){const name=row.querySelector('.entity-row')?.childNodes[0]?.textContent||row.querySelector('b')?.textContent||row.textContent;row.hidden=!!query&&!name.toLocaleLowerCase().includes(query);if(!row.hidden)matches++;}for(const group of document.querySelectorAll('#objects > .tree-group'))group.hidden=!!query&&![...group.querySelectorAll('.tree-entity,.object-row')].some(row=>!row.hidden&&!row.closest('.tree-entity[hidden]'));$('#advanced-node-create').hidden=!!query;$('#object-search-empty').hidden=$('#object-search').hidden||!query||matches>0;}
 function persistPanels(){const panels={leftWidth:getComputedStyle(document.documentElement).getPropertyValue('--foundation-left'),rightWidth:getComputedStyle(document.documentElement).getPropertyValue('--foundation-right'),left:!$('.library').hidden,right:!$('.inspector').hidden};settings.panels=panels;void window.studioDesktop?.updateSettings({panels});}
 function updateLayout(){document.querySelector('main').style.gridTemplateColumns=($('.library').hidden?'0px':'var(--foundation-left)')+' minmax(0,1fr) '+($('.inspector').hidden?'0px':'var(--foundation-right)');persistPanels();}
 function preferences(){h.showDialog(`<h2>환경설정</h2><p>Foundation ${esc(h.desktopInfo?.version||'0.4')} · ${h.desktopInfo?.packaged?'배포 모드':'개발 모드'}</p><label><input id="restore-last" type="checkbox" ${settings.restoreLast?'checked':''}>시작할 때 마지막 프로젝트 복원</label><p>기본 Workspace<br>${esc(h.desktopInfo?.workspace||'')}</p><button type="button" id="preferences-workspace">Workspace 변경</button><p>공용 라이브러리<br>${esc(h.desktopInfo?.sharedRoot||'')}</p><button type="button" id="preferences-shared">공용 라이브러리 연결</button><p class="hint">Git / Blender / Unreal / Unity 실제 연동은 미구현입니다.</p>`);$('#restore-last').onchange=async e=>{settings.restoreLast=e.target.checked;await window.studioDesktop?.updateSettings({restoreLast:settings.restoreLast});};$('#preferences-workspace').onclick=()=>$('#choose-workspace').click();$('#preferences-shared').onclick=()=>run('공용 라이브러리 연결',async()=>{await h.wait();if(await window.studioDesktop?.chooseFolder('shared'))location.reload();});}
 function home(){homeVisible=true;libraryVisible=false;$('#foundation-home').hidden=false;document.body.classList.add('at-home');renderHome();}
 function renderHome(){
  $('#home-project-panel').hidden=libraryVisible;$('#home-library-panel').hidden=!libraryVisible;
  $('#home-projects').setAttribute('aria-pressed',String(!libraryVisible));$('#home-library').setAttribute('aria-pressed',String(libraryVisible));
  assetLibrary.render(libraryVisible&&homeVisible);
  document.querySelectorAll('[data-home-update]').forEach(b=>b.onclick=()=>run('파일 변경 영향 확인',async()=>{const impact=await h.api('/api/foundation/'+b.dataset.homeUpdate+'/usages');if(!confirm('이 파일을 사용하는 등록 프로젝트 '+new Set(impact.uses.map(u=>u.projectId)).size+'개입니다. 선택한 파일의 구조를 비교하고, 피벗·재질 슬롯 변경은 추가 검토를 요청합니다. 업데이트할 파일을 선택할까요?'))return;homeUpdateId=b.dataset.homeUpdate;$('#home-library-files').multiple=false;$('#home-library-files').value='';$('#home-library-files').click();}));
  const recent=recentProjectsMarkup(h.getLibrary().projects,$('#recent-search').value);
  if(recent.html!==lastRecentMarkup){$('#recent-projects').innerHTML=recent.html;lastRecentMarkup=recent.html;}
  $('#recent-count').textContent=recent.count+'개';
  document.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>run('프로젝트 열기',()=>h.openProject(b.dataset.recent)));
  if($('#recent-clear'))$('#recent-clear').onclick=()=>{$('#recent-search').value='';renderHome();$('#recent-search').focus();};
  const warning=h.getLibrary().indexWarning;$('#home-warning').hidden=!warning;$('#home-warning').textContent=warning||'';
  $('#home-paths').innerHTML='<dl><dt>기본 작업 폴더</dt><dd>'+esc(h.desktopInfo?.workspace||'현재 로컬 작업 폴더')+'</dd><dt>공용 에셋 폴더</dt><dd>'+esc(h.desktopInfo?.sharedRoot||'현재 로컬 라이브러리')+'</dd></dl>';
 }
 function render(){bind();const assetId=h.getAssetSelected?.();if(assetId&&!$('#foundation-usage')){$('#inspector-content').insertAdjacentHTML('beforeend','<button id="foundation-usage">에셋 사용처 조회</button><p id="asset-usage-result" class="hint"></p>');$('#foundation-usage').onclick=()=>run('에셋 사용처 검사',async()=>{const result=await h.api('/api/foundation/'+assetId+'/usages');$('#asset-usage-result').textContent=result.uses.map(u=>u.project+' / '+(u.name||'참조')).join(' · ')+(result.unscanned.length?' · 미검사 프로젝트 '+result.unscanned.length:'');});}if(homeVisible)renderHome();const doc=p();$('#project-settings').disabled=!doc;$('#project-copy').disabled=!doc;$('#close-project').disabled=!doc;$('#node-create').disabled=!doc;$('#common-tree').innerHTML=doc?doc.nodes.filter(n=>!doc.entities.some(e=>e.id===n.id)&&!doc.objects.some(o=>o.id===n.id)).map(n=>`<button class="common-node ${h.getSelected()===n.id?'selected':''}" data-node="${n.id}" style="padding-left:${n.parentId?22:6}px"><b>${esc(n.name)}</b><small>${n.type}${n.locked?' · 잠금':''}${n.visible===false?' · 숨김':''}</small></button>`).join(''):'<p class="hint">프로젝트를 열어 주세요.</p>';filterTree();document.querySelectorAll('[data-node]').forEach(b=>{if(!doc?.nodes.some(n=>n.id===b.dataset.node))return;b.onclick=()=>{commonMode=true;h.setSelected(b.dataset.node);h.render();h.selectMesh();};b.oncontextmenu=e=>{e.preventDefault();commonMode=true;h.setSelected(b.dataset.node);h.showDialog(`<h2>객체 작업</h2><button type="button" id="context-inspect">속성 보기</button><button type="button" id="context-delete">삭제</button>`);$('#context-inspect').onclick=()=>{$('#dialog').close();h.render();};$('#context-delete').onclick=()=>{$('#dialog').close();removeNode();};};});}
 function removeNode(){if(confirm('객체와 하위 객체를 삭제할까요? 연결된 생성 결과는 독립 배치로 보존합니다.'))safeEdit(()=>{applyNodeCommand(p(),{type:'delete',id:h.getSelected()});h.setSelected(null);},'객체 삭제','common');}
 function inspect({host=$('#inspector-content'),nodeId=h.getSelected(),embedded=false}={}){const doc=p(),n=doc?.nodes.find(n=>n.id===nodeId);if(!n||!embedded&&(!commonMode||doc.entities.some(e=>e.id===nodeId||e.outputId===nodeId)||doc.objects.some(o=>o.id===nodeId)))return false;
 const $n=s=>host.querySelector(s);const wt=worldTransform(doc,n);host.innerHTML=`<span class="pill">${n.type} · 공통 Scene</span><label>이름<input id="node-name" value="${esc(n.name)}"></label><label>부모 Group<select id="node-parent"><option value="">루트</option>${doc.nodes.filter(g=>g.type==='Group'&&g.id!==n.id).map(g=>`<option value="${g.id}" ${n.parentId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label>레이어<select id="node-layer">${doc.layers.map(l=>`<option value="${l.id}" ${n.layerId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label><input id="node-visible" type="checkbox" ${n.visible?'checked':''}>표시</label><label><input id="node-locked" type="checkbox" ${n.locked?'checked':''}>잠금</label><h4>로컬 위치(m)</h4><div class="vectors">${n.transform.position.map((v,i)=>`<label>${'XYZ'[i]}<input type="number" data-node-axis="${i}" value="${v}" step=".1"></label>`).join('')}</div><h4>크기 배율</h4><div class="vectors">${n.transform.scale.map((v,i)=>`<input type="number" data-node-scale="${i}" value="${v}" min=".001" step=".1" aria-label="배율 ${'XYZ'[i]}">`).join('')}</div><details><summary>회전 고급 설정</summary><label>회전 Quaternion (x,y,z,w)<input id="node-rotation" value="${n.transform.rotation.join(',')}"></label></details><p class="hint">월드 위치 ${wt.position.map(v=>v.toFixed(3)).join(', ')}<br>프로젝트 원점 ${doc.coordinateSystem.origin.join(', ')}<br>${n.geometry?'기존 설계 데이터 연결':'설계 초안 · 유형별 제작 도구는 후속 단계'}</p><details><summary>속성 고급 설정</summary><label>속성 JSON<textarea id="node-properties">${esc(JSON.stringify(n.properties,null,2))}</textarea></label><button id="node-properties-apply">속성 적용</button></details><label>에셋 연결<select id="node-asset"><option value="">연결 없음</option>${Object.values(doc.assets).map(a=>`<option value="${a.id}" ${n.assetRefs.some(r=>r.assetId===a.id)?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><button id="node-delete">객체 삭제</button><details><summary>식별·확장 정보</summary><p class="mono">${n.id}</p><pre>${esc(JSON.stringify(n.modification,null,2))}</pre></details>`;
 const command=(type,value)=>safeEdit(()=>applyNodeCommand(p(),{id:n.id,type,value}),'객체 '+type,'common');
 $n('#node-name').onchange=e=>command('rename',e.target.value);$n('#node-parent').onchange=e=>command('parent',e.target.value);$n('#node-layer').onchange=e=>command('layer',e.target.value);$n('#node-visible').onchange=e=>command('visible',e.target.checked);$n('#node-locked').onchange=e=>command('unlock',e.target.checked);for(const input of host.querySelectorAll('[data-node-axis],[data-node-scale]'))input.onchange=()=>{const transform=structuredClone(n.transform);transform[input.dataset.nodeAxis!==undefined?'position':'scale'][Number(input.dataset.nodeAxis??input.dataset.nodeScale)]=Number(input.value);command('transform',transform);};$n('#node-rotation').onchange=e=>{const t=structuredClone(n.transform);t.rotation=e.target.value.split(',').map(Number);command('transform',t);};$n('#node-properties-apply').onclick=()=>run('속성 적용',()=>command('property',JSON.parse($n('#node-properties').value)));$n('#node-asset').onchange=e=>command('assets',e.target.value?[{assetId:e.target.value,hash:doc.assets[e.target.value].hash}]:[]);$n('#node-delete').onclick=removeNode;return true;
 }
 function appendCommon(nodeId){
  const host=$('#inspector-content'),content=document.createElement('div');if(!inspect({host:content,nodeId,embedded:true}))return;
  content.querySelector('.pill')?.remove();if(p().entities.some(e=>e.id===nodeId))content.querySelector('#node-name')?.closest('label')?.remove();content.querySelector('#node-delete')?.remove();const flags=document.createElement('div');flags.className='inspector-flags';for(const id of ['#node-visible','#node-locked']){const label=content.querySelector(id).closest('label');flags.append(label);}const heading=host.querySelector('.entity-heading,h3');if(heading)heading.after(flags);else host.prepend(flags);
  const details=document.createElement('details');details.id='common-properties';const summary=document.createElement('summary');summary.textContent='배치·계층·연결 고급 설정';details.append(summary,content);host.append(details);
 }
 function projectSettings(){if(!p())return;const doc=p();h.showDialog(`<h2>프로젝트 설정</h2><label>이름<input id="project-display-name" value="${esc(doc.name)}"></label><label>설명<textarea id="project-description">${esc(doc.metadata.description||'')}</textarea></label><p>저장 위치: ${esc(doc.storage?.path)}<br>생성: ${esc(doc.createdAt)}<br>수정: ${esc(doc.updatedAt)}<br>미터 · XY 평면 · Z-up · 오른손</p><h3>프로젝트 원점</h3><div class="vectors">${doc.coordinateSystem.origin.map((v,i)=>`<label>${'XYZ'[i]}<input id="origin-${i}" type="number" value="${v}"></label>`).join('')}</div><p>원점을 바꿔도 실제 월드 배치는 유지합니다. 한 번에 실행 취소할 수 있습니다.</p><button type="button" id="apply-project-settings">설정 적용</button><button type="button" id="validate-project">파일·참조 검사</button><button type="button" id="check-recovery">복구 후보 확인</button><button type="button" id="check-compatibility">이전 Transform 검토</button><div id="validation-result"></div><details><summary>외부 확장 모듈</summary><p>외부 모듈을 호출하는 확장 경로의 상태입니다. 자료 편집·기본 생성·파일 등록·검사는 앱 내장 기능으로 제공됩니다. Blender·엔진의 전체 연동 범위는 제작 현황에서 확인하세요.</p>${extensionRegistry.capabilities().map(m=>`<p>${m.kind}: ${esc(m.reason)}</p>`).join('')}</details>`);$('#apply-project-settings').onclick=()=>run('프로젝트 설정 변경',()=>{const name=$('#project-display-name').value,description=$('#project-description').value,origin=[0,1,2].map(i=>Number($('#origin-'+i).value));if(origin.some((v,i)=>v!==doc.coordinateSystem.origin[i])&&!confirm('월드 배치를 보존하며 프로젝트 원점을 변경할까요?'))return;safeEdit(()=>{doc.name=name;doc.metadata.description=description;rebaseOrigin(doc,origin);},'프로젝트 설정·원점','common');$('#dialog').close();});$('#validate-project').onclick=()=>run('참조 파일 검사',async()=>{const result=await h.api('/api/foundation/'+doc.id+'/inspect');$('#validation-result').textContent=result.issues.length||result.sourceIssues?.length?JSON.stringify({files:result.issues,sources:result.sourceIssues}):'검사 완료: 고정 에셋 파일과 해시 정상. 원격 동기화 미설정.';});$('#check-recovery').onclick=()=>recovery(doc.id);$('#check-compatibility').onclick=()=>{if(!compatibilityReview(h))h.notify('미결 Transform 호환성 항목이 없습니다.');};}
 async function recovery(id){const r=await h.api('/api/foundation/'+id+'/recovery');h.showDialog(`<h2>저장 상태와 복구</h2><p>${r.disk?'정상 저장본을 직접 열지 못했습니다. 검증된 복구 후보를 찾았습니다.':r.autosave?'저장하지 못한 편집 사본이 있습니다.':'현재 저장본과 복구 사본을 확인할 수 있습니다.'}</p>${r.disk?'<button type="button" id="recover-disk">검증된 저장본 복구</button>':''}${r.autosave?'<button type="button" id="recover-auto">편집 사본 복구</button>':''}${r.conflicts?.length?'<p class="failed">외부 동기화 충돌 사본이 있습니다. 원본은 보존되며 일반 저장은 중단됩니다.</p><details><summary>확인이 필요한 파일</summary>'+r.conflicts.map(f=>'<p>'+esc(f)+'</p>').join('')+'</details>':''}<h3>이전 저장 상태</h3><p>선택한 상태를 새 저장본으로 복원합니다. 현재 상태와 이전 기록은 보존합니다.</p><div id="saved-versions">${r.versions.map(v=>'<button type="button" data-restore-version="'+v.generation+'">'+esc(new Date(v.updatedAt).toLocaleString('ko-KR'))+' · '+esc(v.name)+'</button>').join('')}</div>`);const restore=async(mode,generation)=>{if(!confirm('현재 데이터와 기록을 보존하고 선택한 상태를 복원할까요?'))return;await post('/api/foundation/'+id+'/recovery',{mode,generation,expectedGeneration:r.generation});h.clearSaveFailure?.();$('#dialog').close();await h.openProject(id);};for(const [selector,mode]of [['#recover-disk','disk'],['#recover-auto','autosave']])if($(selector))$(selector).onclick=()=>run('복구 사본 적용',()=>restore(mode));document.querySelectorAll('[data-restore-version]').forEach(b=>b.onclick=()=>run('이전 저장 복원',()=>restore('version',b.dataset.restoreVersion)));}
 function onOpen(){commonMode=false;homeVisible=!p();if(p()){assetLibrary.render(false);lastProject=p().id;$('#foundation-home').hidden=true;document.body.classList.remove('at-home');log('프로젝트 열림: '+p().name);const openedId=p().id;void h.api('/api/foundation/'+openedId+'/recovery').then(r=>{if(p()?.id===openedId&&(r.disk||r.autosave))void recovery(openedId);else if(p()?.id===openedId)compatibilityReview(h);}).catch(e=>h.notify(e.message,true));}else home();}
 if(settings.panels){if(settings.panels.leftWidth)document.documentElement.style.setProperty('--foundation-left',settings.panels.leftWidth);if(settings.panels.rightWidth)document.documentElement.style.setProperty('--foundation-right',settings.panels.rightWidth);$('.library').hidden=settings.panels.left===false;$('.inspector').hidden=settings.panels.right===false;updateLayout();}
 bind();return {render,inspect,appendCommon,home,onOpen,assetStatus:state=>{assetMonitor.update(state);assetLibrary.setMonitor(state);},get settings(){return settings;},log,assetKind:()=>$('#asset-kind').value};
}


